		SR.MODEL_CHURN_SPONSORSHIPS as COUNT_IF(sr.CHURN_CLASS = '1') with synonyms=('모델 이탈분류 후원건수') comment='모델이 이탈로 분류한 후원건수. 업무 위험 건수가 아니다.',
